#include <bits/stdc++.h>
using namespace std;
int main(){for(int bits=2;bits<=4;bits++){int n=bits+2;vector<vector<int>>ps;map<vector<int>,int>id;vector<int>p(n);iota(p.begin(),p.end(),0);do{id[p]=ps.size();ps.push_back(p);}while(next_permutation(p.begin(),p.end()));int ns=ps.size();vector<vector<int>>rev(ns);vector<int>disp(ns);for(int s=0;s<ns;s++){int b=0,cov=0;for(int i=0;i<n;i++){int k=ps[s][i],m=k<bits?1<<k:(1<<bits)-1,c=k<bits?1<<k:k==bits?0:(1<<bits)-1;b|=c&~cov;if(m&~cov){for(int j=0;j<n;j++)if(i!=j){auto q=ps[s];if(i<j)rotate(q.begin()+i,q.begin()+i+1,q.begin()+j+1);else rotate(q.begin()+j,q.begin()+i,q.begin()+i+1);rev[id[q]].push_back(s);}}cov|=m;}disp[s]=b;}vector<double>v(ns),nv(ns);double g=0;for(int it=0;it<40;it++){fill(nv.begin(),nv.end(),0);for(int t=0;t<(1<<bits);t++){vector<double>d(ns,1e9);priority_queue<pair<double,int>,vector<pair<double,int>>,greater<pair<double,int>>>pq;for(int s=0;s<ns;s++)if(disp[s]==t)d[s]=v[s],pq.push({v[s],s});while(!pq.empty()){auto [z,s]=pq.top();pq.pop();if(z>d[s]+1e-10)continue;for(int f:rev[s])if(d[f]>z+1+1e-10)d[f]=z+1,pq.push({z+1,f});}for(int s=0;s<ns;s++)nv[s]+=d[s]/(1<<bits);}g=nv[0];for(double &x:nv)x-=g;v.swap(nv);}cout<<bits<<" "<<g<<endl;}}
